from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int], max_workers: int | None = None) -> list[int]:
    """Return parity (0 or 1) of each element, computed via a thread pool in input order."""
    if not xs:
        return []
    with ThreadPoolExecutor(max_workers=max_workers) as executor:
        return list(executor.map(parity, xs))


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([3]) == [1]
    assert parities([4]) == [0]


def test_parities_mixed() -> None:
    assert parities([1, 2, 3, 4, 5, 6]) == [1, 0, 1, 0, 1, 0]


def test_parities_negatives() -> None:
    assert parities([-3, -2, -1, 0]) == [1, 0, 1, 0]


@pytest.mark.parametrize("workers", [1, 2, 4, 16])
def test_parities_order_independent_of_worker_count(workers: int) -> None:
    xs = list(range(100))
    expected = [x % 2 for x in xs]
    assert parities(xs, max_workers=workers) == expected

